pragma solidity >=0.5.0;

/// @title Callback for IUniswapV3PoolActions#swap
/// @notice Any contract that calls IUniswapV3PoolActions#swap must implement this interface
interface IUniswapV3SwapCallback {
    /// @notice Called to `msg.sender` after executing a swap via IUniswapV3Pool#swap.
    /// @dev In the implementation you must pay the pool tokens owed for the swap.
    /// The caller of this method must be checked to be a UniswapV3Pool deployed by the canonical UniswapV3Factory.
    /// amount0Delta and amount1Delta can both be 0 if no tokens were swapped.
    /// @param amount0Delta The amount of token0 that was sent (negative) or must be received (positive) by the pool by
    /// the end of the swap. If positive, the callback must send that amount of token0 to the pool.
    /// @param amount1Delta The amount of token1 that was sent (negative) or must be received (positive) by the pool by
    /// the end of the swap. If positive, the callback must send that amount of token1 to the pool.
    /// @param data Any data passed through by the caller via the IUniswapV3PoolActions#swap call
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}
"},"contracts/amo/UniV2LiquidityAmo.sol":{"content":"//SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

// Contracts
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { SafeMath } from "@openzeppelin/contracts/utils/math/SafeMath.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// Interfaces
import { IERC20WithBurn } from "../interfaces/IERC20WithBurn.sol";
import { IUniswapV2Router } from "../uniswap_V2/IUniswapV2Router.sol";
import { IUniswapV2Pair } from "../uniswap_V2/IUniswapV2Pair.sol";
import { IRdpxEthOracle } from "../interfaces/IRdpxEthOracle.sol";
import { IRdpxV2Core } from "../core/IRdpxV2Core.sol";

// Libraries
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title UniswapV2LiquidityAmo contract
/// @author Dopex
/// @notice The uniswap v2 liquidity amo contract
contract UniV2LiquidityAMO is AccessControl {
  using SafeERC20 for IERC20WithBurn;
  using SafeMath for uint256;

  // ================================ STATE VARIABLES ================================ //
  struct Addresses {
    // token A address
    address tokenA; // rdpx
    // token B address
    address tokenB; // weth
    // pair address
    address pair;
    // rdpxV2Core address
    address rdpxV2Core;
    // rdpx price oracle
    address rdpxOracle;
    // AMM Factory
    address ammFactory;
    // AMM Router
    address ammRouter;
  }

  /// @notice  addresses of the contracts
  Addresses public addresses;

  /// @notice Precision used for prices, percentages and other calculations
  uint256 public constant DEFAULT_PRECISION = 1e8;

  /// @notice The slippage tolernce in swaps in 1e8 precision
  uint256 public slippageTolerance = 5e5; // 0.5%

  /// @notice LP token Balance
  uint256 public lpTokenBalance;

  // ================================ CONSTRUCTOR ================================ //
  constructor() {
    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
  }

  // ================================ ADMIN FUNCTIONS ================================ //

  /**
   * @notice Set the addresses of the contracts
   * @dev    Can only be called by admin
   * @param  _tokenA the token A address
   * @param  _tokenB the token B address
   * @param _pair the pair address
   * @param _rdpxV2Core the rdpxV2Core address
   * @param _rdpxOracle the rdpx price oracle
   * @param _ammFactory the AMM Factory
   * @param _ammRouter the AMM Router
   **/
  function setAddresses(
    address _tokenA,
    address _tokenB,
    address _pair,
    address _rdpxV2Core,
    address _rdpxOracle,
    address _ammFactory,
    address _ammRouter
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(
      _tokenA != address(0) &&
        _tokenB != address(0) &&
        _pair != address(0) &&
        _rdpxV2Core != address(0) &&
        _rdpxOracle != address(0) &&
        _ammFactory != address(0) &&
        _ammRouter != address(0),
      "reLPContract: address cannot be 0"
    );
    addresses = Addresses({
      tokenA: _tokenA,
      tokenB: _tokenB,
      pair: _pair,
      rdpxV2Core: _rdpxV2Core,
      rdpxOracle: _rdpxOracle,
      ammFactory: _ammFactory,
      ammRouter: _ammRouter
    });
  }

  /**
   * @notice sets the slippage tolerance
   * @dev    Can only be called by admin
   * @param  _slippageTolerance the slippage tolerance
   */
  function setSlippageTolerance(
    uint256 _slippageTolerance
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(
      _slippageTolerance > 0,
      "reLPContract: slippage tolerance must be greater than 0"
    );
    slippageTolerance = _slippageTolerance;
  }

  /**
   * @notice Approve a contract to spend a certain amount of tokens
   * @dev    Can only be called by admin
   * @param  _token the address of the token to approve
   * @param  _spender the address of the contract to approve
   * @param  _amount the amount to approve
   */
  function approveContractToSpend(
    address _token,
    address _spender,
    uint256 _amount
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(_token != address(0), "reLPContract: token cannot be 0");
    require(_spender != address(0), "reLPContract: spender cannot be 0");
    require(_amount > 0, "reLPContract: amount must be greater than 0");
    IERC20WithBurn(_token).approve(_spender, _amount);
  }

  /**
   * @notice Transfers all funds to msg.sender
   * @dev    Can only be called by the owner
   * @param  tokens The list of erc20 tokens to withdraw
   **/
  function emergencyWithdraw(
    address[] calldata tokens
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    IERC20WithBurn token;

    for (uint256 i = 0; i < tokens.length; i++) {
      token = IERC20WithBurn(tokens[i]);
      token.safeTransfer(msg.sender, token.balanceOf(address(this)));
    }

    emit LogEmergencyWithdraw(msg.sender, tokens);
  }

  // ================================ INTERNAL FUNCTIONS ================================ //

  /**
   * @dev sends token A and B to the rdpxV2Core
   */
  function _sendTokensToRdpxV2Core() internal {
    uint256 tokenABalance = IERC20WithBurn(addresses.tokenA).balanceOf(
      address(this)
    );
    uint256 tokenBBalance = IERC20WithBurn(addresses.tokenB).balanceOf(
      address(this)
    );
    // transfer token A and B from this contract to the rdpxV2Core
    IERC20WithBurn(addresses.tokenA).safeTransfer(
      addresses.rdpxV2Core,
      tokenABalance
    );
    IERC20WithBurn(addresses.tokenB).safeTransfer(
      addresses.rdpxV2Core,
      tokenBBalance
    );

    emit LogAssetsTransfered(msg.sender, tokenABalance, tokenBBalance);
  }

  // ================================ AMO FUNCTIONS ================================ //

  /**
   * @dev adds liquidity to the uni v2 pool
   * @param tokenAAmount the amount of token A to add
   * @param tokenBAmount the amount of token B to add
   * @param tokenAAmountMin the minimum amount of token A to add
   * @param tokenBAmountMin the minimum amount of token B to add
   */
  function addLiquidity(
    uint256 tokenAAmount,
    uint256 tokenBAmount,
    uint256 tokenAAmountMin,
    uint256 tokenBAmountMin
  )
    external
    onlyRole(DEFAULT_ADMIN_ROLE)
    returns (uint256 tokenAUsed, uint256 tokenBUsed, uint256 lpReceived)
  {
    // approve the AMM Router
    IERC20WithBurn(addresses.tokenA).safeApprove(
      addresses.ammRouter,
      tokenAAmount
    );
    IERC20WithBurn(addresses.tokenB).safeApprove(
      addresses.ammRouter,
      tokenBAmount
    );

    // transfer token A and B from the rdpxV2Core to this contract
    IERC20WithBurn(addresses.tokenA).safeTransferFrom(
      addresses.rdpxV2Core,
      address(this),
      tokenAAmount
    );
    IERC20WithBurn(addresses.tokenB).safeTransferFrom(
      addresses.rdpxV2Core,
      address(this),
      tokenBAmount
    );

    // add Liquidity
    (tokenAUsed, tokenBUsed, lpReceived) = IUniswapV2Router(addresses.ammRouter)
      .addLiquidity(
        addresses.tokenA,
        addresses.tokenB,
        tokenAAmount,
        tokenBAmount,
        tokenAAmountMin,
        tokenBAmountMin,
        address(this),
        block.timestamp + 1
      );

    // update LP token Balance
    lpTokenBalance += lpReceived;

    // send unused token A and token B back to rdpxV2Core
    _sendTokensToRdpxV2Core();

    emit LogAddLiquidity(
      msg.sender,
      tokenAAmount,
      tokenBAmount,
      tokenAAmountMin,
      tokenBAmountMin,
      tokenAUsed,
      tokenBUsed,
      lpReceived
    );
  }

  /**
   * @dev removes liquidity from the uni v2 pool
   * @param lpAmount the amount of LP tokens to remove
   * @param tokenAAmountMin the minimum amount of token A to receive
   * @param tokenBAmountMin the minimum amount of token B to receive
   */
  function removeLiquidity(
    uint256 lpAmount,
    uint256 tokenAAmountMin,
    uint256 tokenBAmountMin
  )
    external
    onlyRole(DEFAULT_ADMIN_ROLE)
    returns (uint256 tokenAReceived, uint256 tokenBReceived)
  {
    // approve the AMM Router
    IERC20WithBurn(addresses.pair).safeApprove(addresses.ammRouter, lpAmount);

    // remove liquidity
    (tokenAReceived, tokenBReceived) = IUniswapV2Router(addresses.ammRouter)
      .removeLiquidity(
        addresses.tokenA,
        addresses.tokenB,
        lpAmount,
        tokenAAmountMin,
        tokenBAmountMin,
        address(this),
        block.timestamp + 1
      );

    // update LP token Balance
    lpTokenBalance -= lpAmount;

    // send unused token A and token B back to rdpxV2Core
    _sendTokensToRdpxV2Core();

    emit LogRemoveLiquidity(
      msg.sender,
      lpAmount,
      tokenAAmountMin,
      tokenBAmountMin,
      tokenAReceived,
      tokenBReceived
    );
  }

  /**
   * @dev swaps token 1 for token 2
   * @param token1Amount the amount of token A to swap
   * @param token2AmountOutMin the minimum amount of token B to receive
   * @param swapTokenAForTokenB whether to swap token A for token B
   */
  function swap(
    uint256 token1Amount,
    uint256 token2AmountOutMin,
    bool swapTokenAForTokenB
  ) external onlyRole(DEFAULT_ADMIN_ROLE) returns (uint256 token2Amount) {
    address token1;
    address token2;

    // check to see if we are swapping token A for token B
    if (swapTokenAForTokenB) {
      token1 = addresses.tokenA;
      token2 = addresses.tokenB;
    } else {
      token1 = addresses.tokenB;
      token2 = addresses.tokenA;
    }
    // transfer token A from the rdpxV2Core to this contract
    IERC20WithBurn(token1).safeTransferFrom(
      addresses.rdpxV2Core,
      address(this),
      token1Amount
    );

    // approve the AMM Router
    IERC20WithBurn(token1).safeApprove(addresses.ammRouter, token1Amount);

    address[] memory path;
    path = new address[](2);
    path[0] = token1;
    path[1] = token2;

    // swap token A for token B
    token2Amount = IUniswapV2Router(addresses.ammRouter)
      .swapExactTokensForTokens(
        token1Amount,
        token2AmountOutMin,
        path,
        address(this),
        block.timestamp + 1
      )[path.length - 1];

    // send tokens back to rdpxV2Core
    _sendTokensToRdpxV2Core();

    emit LogSwap(
      msg.sender,
      token1Amount,
      token2AmountOutMin,
      swapTokenAForTokenB,
      token2Amount
    );
  }

  // ================================ EXTERNAL FUNCTIONS ================================ //

  /**
   * @notice Syncs asset reserves with contract balances
   **/
  function sync() external {
    lpTokenBalance = IERC20WithBurn(addresses.pair).balanceOf(address(this));
  }

  // ================================ VIEW FUNCTIONS ================================ //
  /**
   * @notice Returns the LP token balance in weth
   * @dev returns LP token balance
   * @return lpTokenBalanceInWeth the LP token balance in weth
   */
  function getLpTokenBalanceInWeth() external view returns (uint256) {
    return (lpTokenBalance * getLpPrice()) / 1e8;
  }

  /**
   * @notice Returns the price of a rDPX/ETH Lp token against the alpha token
   * @dev    Price is in 1e8 Precision
   * @return uint256 LP price
   **/
  function getLpPrice() public view returns (uint256) {
    return IRdpxEthOracle(addresses.rdpxOracle).getLpPriceInEth();
  }

  // ================================ Events FUNCTIONS ================================ //

  event LogAddLiquidity(
    address indexed sender,
    uint256 tokenAAmount,
    uint256 tokenBAmount,
    uint256 tokenAAmountMin,
    uint256 tokenBAmountMin,
    uint256 tokenAUsed,
    uint256 tokenBUsed,
    uint256 lpReceived
  );

  event LogRemoveLiquidity(
    address indexed sender,
    uint256 lpAmount,
    uint256 tokenAAmountMin,
    uint256 tokenBAmountMin,
    uint256 tokenAReceived,
    uint256 tokenBReceived
  );

  event LogSwap(
    address indexed sender,
    uint256 token1Amount,
    uint256 token2AmountOutMin,
    bool swapTokenAForTokenB,
    uint256 token2Amount
  );

  event LogAssetsTransfered(
    address indexed sender,
    uint256 tokenAAmount,
    uint256 tokenBAmount
  );

  event LogEmergencyWithdraw(address sender, address[] tokens);
}
"},"contracts/amo/UniV3LiquidityAmo.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ERC721Holder } from "@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol";
import { SafeMath } from "@openzeppelin/contracts/utils/math/SafeMath.sol";
import { TransferHelper } from "../libraries/TransferHelper.sol";
import { IRdpxV2Core } from "../core/IRdpxV2Core.sol";

// Uniswamp V3
import "../uniswap_V3/IUniswapV3Factory.sol";
import "../uniswap_V3/libraries/TickMath.sol";
import "../uniswap_V3/libraries/LiquidityAmounts.sol";
import "../uniswap_V3/periphery/interfaces/INonfungiblePositionManager.sol";
import "../uniswap_V3/IUniswapV3Pool.sol";
import "../uniswap_V3/ISwapRouter.sol";

// Interfaces
import { IERC20WithBurn } from "../interfaces/IERC20WithBurn.sol";

abstract contract OracleLike {
  function read() external view virtual returns (uint);

  function uniswapPool() external view virtual returns (address);
}

contract UniV3LiquidityAMO is AccessControl, ERC721Holder {
  using SafeMath for uint256;
  using SafeERC20 for IERC20WithBurn;

  /* ========== STATE VARIABLES ========== */

  // Uniswap v3
  IUniswapV3Factory public univ3_factory;
  INonfungiblePositionManager public univ3_positions;
  ISwapRouter public univ3_router;

  // Details about the AMO's uniswap positions
  struct Position {
    uint256 token_id;
    address collateral_address;
    uint128 liquidity; // the liquidity of the position
    int24 tickLower; // the tick range of the position
    int24 tickUpper;
    uint24 fee_tier;
  }

  // Add liquidity param
  struct AddLiquidityParams {
    address _tokenA;
    address _tokenB;
    int24 _tickLower;
    int24 _tickUpper;
    uint24 _fee;
    uint256 _amount0Desired;
    uint256 _amount1Desired;
    uint256 _amount0Min;
    uint256 _amount1Min;
  }

  // Array of all Uni v3 NFT positions held by the AMO
  Position[] public positions_array;

  // Map token_id to Position
  mapping(uint256 => Position) public positions_mapping;

  // Rdpx address
  address public rdpx;

  // RdpxV2Core address
  address public rdpxV2Core;

  /* ========== CONSTRUCTOR ========== */

  constructor(address _rdpx, address _rdpxV2Core) {
    rdpx = _rdpx;
    rdpxV2Core = _rdpxV2Core;

    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);

    univ3_factory = IUniswapV3Factory(
      0x1F98431c8aD98523631AE4a59f267346ea31F984
    );
    univ3_positions = INonfungiblePositionManager(
      0xC36442b4a4522E871399CD717aBDD847Ab11FE88
    );
    univ3_router = ISwapRouter(0xE592427A0AEce92De3Edee1F18E0157C05861564);
  }

  /* ========== VIEWS ========== */

  // Returns this contract's liquidity in a specific [Rdpx]-[collateral] uni v3 pool
  function liquidityInPool(
    address _collateral_address,
    int24 _tickLower,
    int24 _tickUpper,
    uint24 _fee
  ) public view returns (uint128) {
    IUniswapV3Pool get_pool = IUniswapV3Pool(
      univ3_factory.getPool(address(rdpx), _collateral_address, _fee)
    );

    // goes into the pool's positions mapping, and grabs this address's liquidity
    (uint128 liquidity, , , , ) = get_pool.positions(
      keccak256(abi.encodePacked(address(this), _tickLower, _tickUpper))
    );
    return liquidity;
  }

  // Only counts non-withdrawn positions
  function numPositions() public view returns (uint256) {
    return positions_array.length;
  }

  /* ========== RESTRICTED FUNCTIONS, BUT CUSTODIAN CAN CALL ========== */

  // Iterate through all positions and collect fees accumulated
  function collectFees() external onlyRole(DEFAULT_ADMIN_ROLE) {
    for (uint i = 0; i < positions_array.length; i++) {
      Position memory current_position = positions_array[i];
      INonfungiblePositionManager.CollectParams
        memory collect_params = INonfungiblePositionManager.CollectParams(
          current_position.token_id,
          rdpxV2Core,
          type(uint128).max,
          type(uint128).max
        );

      // Send to custodian address
      univ3_positions.collect(collect_params);
    }
  }

  /* ---------------------------------------------------- */
  /* ---------------------- Uni v3 ---------------------- */
  /* ---------------------------------------------------- */

  function approveTarget(
    address _target,
    address _token,
    uint256 _amount,
    bool use_safe_approve
  ) public onlyRole(DEFAULT_ADMIN_ROLE) {
    if (use_safe_approve) {
      // safeApprove needed for USDT and others for the first approval
      // You need to approve 0 every time beforehand for USDT: it resets
      TransferHelper.safeApprove(_token, _target, _amount);
    } else {
      IERC20WithBurn(_token).approve(_target, _amount);
    }
  }

  // IUniswapV3Pool public current_uni_pool; // only used for mint callback; is set and accessed during execution of addLiquidity()
  function addLiquidity(
    AddLiquidityParams memory params
  ) public onlyRole(DEFAULT_ADMIN_ROLE) {
    IERC20WithBurn(params._tokenA).transferFrom(
      rdpxV2Core,
      address(this),
      params._amount0Desired
    );
    IERC20WithBurn(params._tokenB).transferFrom(
      rdpxV2Core,
      address(this),
      params._amount1Desired
    );

    IERC20WithBurn(params._tokenA).approve(
      address(univ3_positions),
      params._amount0Desired
    );
    IERC20WithBurn(params._tokenB).approve(
      address(univ3_positions),
      params._amount1Desired
    );

    INonfungiblePositionManager.MintParams
      memory mintParams = INonfungiblePositionManager.MintParams(
        params._tokenA,
        params._tokenB,
        params._fee,
        params._tickLower,
        params._tickUpper,
        params._amount0Desired,
        params._amount1Desired,
        params._amount0Min,
        params._amount1Min,
        address(this),
        type(uint256).max
      );

    (uint256 tokenId, uint128 amountLiquidity, , ) = univ3_positions.mint(
      mintParams
    );

    Position memory pos = Position(
      tokenId,
      params._tokenA == address(rdpx) ? params._tokenB : params._tokenA,
      amountLiquidity,
      params._tickLower,
      params._tickUpper,
      params._fee
    );

    positions_array.push(pos);
    positions_mapping[tokenId] = pos;

    // send tokens to rdpxV2Core
    _sendTokensToRdpxV2Core(params._tokenA, params._tokenB);
  }

  function removeLiquidity(
    uint256 positionIndex,
    uint256 minAmount0,
    uint256 minAmount1
  ) public onlyRole(DEFAULT_ADMIN_ROLE) {
    Position memory pos = positions_array[positionIndex];
    INonfungiblePositionManager.CollectParams
      memory collect_params = INonfungiblePositionManager.CollectParams(
        pos.token_id,
        rdpxV2Core,
        type(uint128).max,
        type(uint128).max
      );

    (
      ,
      ,
      address tokenA,
      address tokenB,
      ,
      ,
      ,
      uint128 liquidity,
      ,
      ,
      ,

    ) = univ3_positions.positions(pos.token_id);

    // remove liquidity
    INonfungiblePositionManager.DecreaseLiquidityParams
      memory decreaseLiquidityParams = INonfungiblePositionManager
        .DecreaseLiquidityParams(
          pos.token_id,
          liquidity,
          minAmount0,
          minAmount1,
          block.timestamp
        );

    univ3_positions.decreaseLiquidity(decreaseLiquidityParams);

    univ3_positions.collect(collect_params);

    univ3_positions.burn(pos.token_id);

    positions_array[positionIndex] = positions_array[
      positions_array.length - 1
    ];
    positions_array.pop();
    delete positions_mapping[pos.token_id];

    // send tokens to rdpxV2Core
    _sendTokensToRdpxV2Core(tokenA, tokenB);

    emit log(positions_array.length);
    emit log(positions_mapping[pos.token_id].token_id);
  }

  // Swap tokenA into tokenB using univ3_router.ExactInputSingle()
  // Uni V3 only
  function swap(
    address _tokenA,
    address _tokenB,
    uint24 _fee_tier,
    uint256 _amountAtoB,
    uint256 _amountOutMinimum,
    uint160 _sqrtPriceLimitX96
  ) public onlyRole(DEFAULT_ADMIN_ROLE) returns (uint256) {
    // transfer token from rdpx v2 core
    IERC20WithBurn(_tokenA).transferFrom(
      rdpxV2Core,
      address(this),
      _amountAtoB
    );

    ISwapRouter.ExactInputSingleParams memory swap_params = ISwapRouter
      .ExactInputSingleParams(
        _tokenA,
        _tokenB,
        _fee_tier,
        address(this),
        2105300114, // Expiration: a long time from now
        _amountAtoB,
        _amountOutMinimum,
        _sqrtPriceLimitX96
      );

    // Approval
    TransferHelper.safeApprove(_tokenA, address(univ3_router), _amountAtoB);

    uint256 amountOut = univ3_router.exactInputSingle(swap_params);

    _sendTokensToRdpxV2Core(_tokenA, _tokenB);
    return amountOut;
  }

  /* ========== OWNER / GOVERNANCE FUNCTIONS ONLY ========== */
  // Only owner or timelock can call, to limit risk

  function recoverERC20(
    address tokenAddress,
    uint256 tokenAmount
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    // Can only be triggered by owner or governance, not custodian
    // Tokens are sent to the custodian, as a sort of safeguard
    TransferHelper.safeTransfer(tokenAddress, rdpxV2Core, tokenAmount);

    emit RecoveredERC20(tokenAddress, tokenAmount);
  }

  function recoverERC721(
    address tokenAddress,
    uint256 token_id
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    // Only the owner address can ever receive the recovery withdrawal
    // INonfungiblePositionManager inherits IERC721 so the latter does not need to be imported
    INonfungiblePositionManager(tokenAddress).safeTransferFrom(
      address(this),
      rdpxV2Core,
      token_id
    );
    emit RecoveredERC721(tokenAddress, token_id);
  }

  // Generic proxy
  function execute(
    address _to,
    uint256 _value,
    bytes calldata _data
  ) external onlyRole(DEFAULT_ADMIN_ROLE) returns (bool, bytes memory) {
    (bool success, bytes memory result) = _to.call{ value: _value }(_data);
    return (success, result);
  }

  /* ========== INTERNAL ========== */

  /**
   * @dev sends token A and B to the rdpxV2Core
   */
  function _sendTokensToRdpxV2Core(address tokenA, address tokenB) internal {
    uint256 tokenABalance = IERC20WithBurn(tokenA).balanceOf(address(this));
    uint256 tokenBBalance = IERC20WithBurn(tokenB).balanceOf(address(this));
    // transfer token A and B from this contract to the rdpxV2Core
    IERC20WithBurn(tokenA).safeTransfer(rdpxV2Core, tokenABalance);
    IERC20WithBurn(tokenB).safeTransfer(rdpxV2Core, tokenBBalance);

    // sync token balances
    IRdpxV2Core(rdpxV2Core).sync();

    emit LogAssetsTransfered(tokenABalance, tokenBBalance, tokenA, tokenB);
  }

  /* ========== EVENTS ========== */

  event RecoveredERC20(address token, uint256 amount);
  event RecoveredERC721(address token, uint256 id);
  event LogAssetsTransfered(
    uint256 tokenAAmount,
    uint256 tokenBAmount,
    address tokenAAddress,
    address tokenBAddress
  );
  /*
   **  burn tokenAmount from the recipient and send tokens to the receipient
   */
  event log(uint);
}
"},"contracts/core/IRdpxV2Core.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

interface IRdpxV2Core {
  // ================================ STRUCTS ================================ //

  /// @dev Peripheral addresses for the RdpxV2Core contract
  struct Addresses {
    address dopexAMMRouter;
    address dpxEthCurvePool;
    address rdpxDecayingBonds;
    address perpetualAtlanticVault;
    address perpetualAtlanticVaultLP;
    address rdpxReserve;
    address rdpxV2ReceiptToken;
    address feeDistributor;
    address reLPContract;
    address receiptTokenBonds;
  }

  /// @dev Peripheral addresses for the RdpxV2Core pricing oracles
  struct PricingOracleAddresses {
    address rdpxPriceOracle;
    address dpxEthPriceOracle;
  }

  /// @dev Struct containing the variables for delegate's position
  struct Delegate {
    address owner;
    uint256 amount;
    uint256 fee;
    uint256 activeCollateral;
  }

  /// @dev Struct containing the variables for a bond
  struct Bond {
    uint256 amount;
    uint256 maturity;
    uint256 timestamp;
  }

  /// @dev Struct containing the the rdpxV2Core reserve asset data
  struct ReserveAsset {
    address tokenAddress;
    uint256 tokenBalance;
    string tokenSymbol;
  }

  /// @dev Struct containing the return values for _bondWithDelegate
  struct BondWithDelegateReturnValue {
    uint256 delegateReceiptTokenAmount;
    uint256 bondAmountForUser;
    uint256 rdpxRequired;
    uint256 wethRequired;
  }

  // ================================ FUNCTIONS ================================ //
  function sync() external;

  // ================================ EVENTS ================================ //

  /// @notice Emitted when rdpxV2Core reserves are synced
  event LogSync();

  /// @notice Emitted when funds are withdrawn in an emergency
  /// @param sender msg.sender
  event LogEmergencyWithdraw(address sender, address[] tokens);

  /// @notice Emitted when addresses are set
  /// @param addresses The Addresses struct
  event LogSetAddresses(Addresses addresses);

  /// @notice Emitted when pricing oracle addresses are set
  /// @param pricingOracleAddresses The pricingOracleAddresses struct
  event LogSetPricingOracleAddresses(
    PricingOracleAddresses pricingOracleAddresses
  );

  /// @notice Emitted when the bond discount factor is set
  /// @param bondDiscountFactor The Bond Discount Factor
  event LogSetBondDiscountFactor(uint256 bondDiscountFactor);

  /// @notice Emitted when the reLP factor is set
  /// @param reLpFactor The reLP factor
  event LogSetReLpFactor(uint256 reLpFactor);

  /// @notice Emitted when the put option requirement is changed
  /// @param putOptionRequirement The put option requirement
  event LogSetputOptionsRequired(bool putOptionRequirement);

  /// @notice Emitted when the slippage tolerance is set
  /// @param slippageTolerance The Slippage tolerance
  event LogSetSlippageTolerance(uint256 slippageTolerance);

  /// @notice Emitted when the bond maturity is set
  /// @param bondMaturity The Bond Maturity
  event LogSetBondMaturity(uint256 bondMaturity);

  /// @notice Emitted when a bond is minted
  /// @param rdpxPaid the amount of rdpx paid
  /// @param alphaTokenPaid the amount of alphaTokenPaid
  /// @param receiptTokenAmount the amount of receipt tokens received
  event LogBond(
    uint256 rdpxPaid,
    uint256 alphaTokenPaid,
    uint256 receiptTokenAmount
  );

  /// @notice Emitted when a bond is minted via delegation
  /// @param to the address to which the bond is minted
  /// @param delegateIds array of the delegate ids
  /// @param amounts array of amounts used from the delegates
  /// @param rdpxBondId the bond id of the rdpx decaying bond
  /// @param userReceiptTokenAmount the amount of receipt tokens received by the user
  /// @param delegateReceiptTokenAmounts the amount of receipt tokens received by the delegates
  event LogBondWithDelegate(
    address to,
    uint256[] delegateIds,
    uint256[] amounts,
    uint256 rdpxBondId,
    uint256 userReceiptTokenAmount,
    uint256[] delegateReceiptTokenAmounts
  );

  /// @notice Emitted when the rdpxV2Core settles the perp-vault options
  /// @param optionIds the optionIds
  event LogSettle(uint256[] optionIds);

  /// @notice Emitted when the rdpxV2Core pays funding
  /// @param epoch the epoch for which to pay funding for
  /// @param funding the amount of funding to pay
  event LogProvideFunding(uint256 epoch, uint256 funding);

  /// @notice Emitted when someone delegates
  /// @param amount the amount to delegate
  event LogAddToDelegate(uint256 amount, uint256 fees, uint256 delegateId);

  /// @notice Emitted when a delegate withdraws
  /// @param delegateId the delegate id
  /// @param amount the amount withdrawn
  event LogDelegateWithdraw(uint256 delegateId, uint256 amount);

  /// @notice Emitted when upper depeg fn is called
  /// @param amount The amount of dpxEth minted
  /// @param wethReceived The amount of alpha token received
  event LogUpperDepeg(uint256 amount, uint256 wethReceived);

  /// @notice Emitted when lower depeg fn is called
  /// @param rdpxAmount The amount of rdpx used
  /// @param wethAmount The amount of weth used
  /// @param dpxEthReceived The amount of dpxEth received
  event LogLowerDepeg(
    uint256 rdpxAmount,
    uint256 wethAmount,
    uint256 dpxEthReceived
  );

  /// @notice Emitted when a new asset is added to the rdpxV2Core
  /// @param asset the address of the asset
  /// @param assetSymbol the symbol of the asset
  event LogAssetAddedTotokenReserves(address asset, string assetSymbol);

  /// @notice Emitted when a new asset is removed from the rdpxV2Core
  /// @param assetSymbol the symbol of the asset
  event LogAssetRemovedFromtokenReserves(string assetSymbol, uint256 index);

  /// @notice Emitted when rdpx burn percentage is set
  /// @param rdpxBurnPercentage the percentage of rdpx to burn
  event LogSetRdpxBurnPercentage(uint256 rdpxBurnPercentage);

  /// @notice Emitted when rdpx fee percentage is set
  /// @param rdpxFeePercentage the percentage of rdpx to burn
  event LogSetRdpxFeePercentage(uint256 rdpxFeePercentage);

  /// @notice Emitted when isReLpActive is set
  /// @param isReLPActive the boolean value of isReLpActive
  event LogSetIsReLPActive(bool isReLPActive);

  /// @notice Emitted when a bond is redeemed
  /// @param to the address to which the receipt tokens are sent
  /// @param amount the amount of receipt tokens redeemed
  event LogRedeem(address to, uint256 amount);
}
"},"contracts/core/RdpxV2Bond.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import { ERC721Enumerable } from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import { Pausable } from "../helper/Pausable.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ERC721Burnable } from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Burnable.sol";
import { Counters } from "@openzeppelin/contracts/utils/Counters.sol";

contract RdpxV2Bond is
  ERC721,
  ERC721Enumerable,
  Pausable,
  AccessControl,
  ERC721Burnable
{
  using Counters for Counters.Counter;

  Counters.Counter private _tokenIdCounter;

  bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

  constructor() ERC721("rDPX V2 Bond", "rDPXV2Bond") {
    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    _setupRole(MINTER_ROLE, msg.sender);
  }

  function pause() public onlyRole(DEFAULT_ADMIN_ROLE) {
    _pause();
  }

  function unpause() public onlyRole(DEFAULT_ADMIN_ROLE) {
    _unpause();
  }

  function mint(
    address to
  ) public onlyRole(MINTER_ROLE) returns (uint256 tokenId) {
    tokenId = _tokenIdCounter.current();
    _tokenIdCounter.increment();
    _mint(to, tokenId);
  }

  function _beforeTokenTransfer(
    address from,
    address to,
    uint256 tokenId,
    uint256 batchSize
  ) internal override(ERC721, ERC721Enumerable) {
    _whenNotPaused();
    super._beforeTokenTransfer(from, to, tokenId, batchSize);
  }

  // The following functions are overrides required by Solidity.

  function supportsInterface(
    bytes4 interfaceId
  )
    public
    view
    override(ERC721, ERC721Enumerable, AccessControl)
    returns (bool)
  {
    return super.supportsInterface(interfaceId);
  }
}
"},"contracts/core/RdpxV2Core.sol":{"content":"//SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

// Contracts
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ERC721Holder } from "@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol";
import { ContractWhitelist } from "../helper/ContractWhitelist.sol";
import { Pausable } from "../helper/Pausable.sol";
import { RdpxV2Bond } from "./RdpxV2Bond.sol";

// Interfaces
import { IERC20WithBurn } from "../interfaces/IERC20WithBurn.sol";
import { IUniswapV2Router } from "../uniswap_V2/IUniswapV2Router.sol";
import { IStableSwap } from "../interfaces/IStableSwap.sol";
import { IRdpxDecayingBonds } from "../decaying-bonds/IRdpxDecayingBonds.sol";
import { IDpxEthToken } from "../dpxETH/IDpxEthToken.sol";
import { IPerpetualAtlanticVault } from "../perp-vault/IPerpetualAtlanticVault.sol";
import { IRdpxEthOracle } from "../interfaces/IRdpxEthOracle.sol";
import { IDpxEthOracle } from "../oracles/IDpxEthOracle.sol";
import { IRdpxReserve } from "../reserve/IRdpxReserve.sol";
import { IRdpxV2Core } from "./IRdpxV2Core.sol";
import { IRdpxV2ReceiptToken } from "../interfaces/IRdpxV2ReceiptToken.sol";
import { IReLP } from "../interfaces/IReLP.sol";

// Libraries
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title Rdpx V2 Core contract
/// @author Dopex
/// @notice The Rdpx V2 Corecontracts handles the bonding mechanism and peg of DpxEth
contract RdpxV2Core is
  IRdpxV2Core,
  AccessControl,
  ContractWhitelist,
  ERC721Holder,
  Pausable
{
  using EnumerableSet for EnumerableSet.AddressSet;
  using SafeERC20 for IERC20WithBurn;
  using SafeERC20 for IDpxEthToken;

  // ================================ STATE VARIABLES ================================ //

  /// @notice Addresses used by the contract
  Addresses public addresses;

  /// @notice The pricing oracle addresses
  PricingOracleAddresses public pricingOracleAddresses;

  /* Inital tokens in the reserve
     index0: ZERO address
     index1: weth
     index2: rdpx
     index3: dpxEth
     index4: crv
  */

  /// @notice Array containg the reserve assets
  ReserveAsset[] public reserveAsset;

  /// @notice Array that contains the addresses of the AMO
  address[] public amoAddresses;

  /// @notice Token address that dpxEth is pegged to
  address public weth;

  /// @notice Array that contains the symbol of the reserve tokens
  string[] public reserveTokens;

  /// @notice Mapping that contains the index for a specific token in the reserves
  mapping(string => uint256) public reservesIndex;

  /// @dev Bond id => Bond
  mapping(uint256 => Bond) public bonds;

  /// @dev Option id => owned or not (boolean)
  mapping(uint256 => bool) public optionsOwned;

  /// @dev Funding paid for epoch
  mapping(uint256 => bool) public fundingPaidFor;

  /// @notice Precision used for prices, percentages and other calculations
  uint256 public constant DEFAULT_PRECISION = 1e8;

  /// @notice rDPX Ratio required when bonding
  uint256 public constant RDPX_RATIO_PERCENTAGE = 25 * DEFAULT_PRECISION;

  /// @notice ETH Ratio required when bonding
  uint256 public constant ETH_RATIO_PERCENTAGE = 75 * DEFAULT_PRECISION;

  /// @notice The % of rdpx to burn while bonding
  uint256 public rdpxBurnPercentage = 50 * DEFAULT_PRECISION;

  /// @notice The % of rdpx sent to fee distributor while bonding
  uint256 public rdpxFeePercentage = 50 * DEFAULT_PRECISION;

  /// @notice The slippage tolernce in swaps in 1e8 precision
  uint256 public slippageTolerance = 5e5; // 0.5%

  /// @notice Liquidity slippage tolerance
  uint256 public liquiditySlippageTolerance = 5e5; // 0.5%

  /// @notice Bond maturity
  uint256 public bondMaturity;

  /// @notice rDPX LP bond discount factor
  uint256 public bondDiscountFactor;

  /// @notice Total weth delegated
  uint256 public totalWethDelegated;

  /// @notice Whether reLP is active or not
  bool public isReLPActive;

  /// @notice Whether put options are requred
  bool public putOptionsRequired;

  /// @notice Delegates array
  Delegate[] public delegates;

  // ================================ CONSTRUCTOR ================================ //
  constructor(address _weth) {
    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    weth = _weth;

    // add Zero asset to reserveAsset
    ReserveAsset memory zeroAsset = ReserveAsset({
      tokenAddress: address(0),
      tokenBalance: 0,
      tokenSymbol: "ZERO"
    });
    reserveAsset.push(zeroAsset);
    putOptionsRequired = true;
  }

