  function isContract(address addr) public view returns (bool) {
    uint256 size;
    assembly {
      size := extcodesize(addr)
    }
    return size > 0;
  }

  /*==== EVENTS ====*/

  event AddToContractWhitelist(address indexed _contract);

  event RemoveFromContractWhitelist(address indexed _contract);
}
