interface IDpxEthOracle {
  /// @notice Gets the price of dpxETH in ETH
  /// @return price
  function getDpxEthPriceInEth() external view returns (uint256);

  /// @notice Gets the price of ETH in dpxETH
  /// @return price
  function getEthPriceInDpxEth() external view returns (uint256);
}
"},"contracts/perp-vault/IPerpetualAtlanticVault.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

interface IPerpetualAtlanticVault {
  // ================================ VIEWS ================================ //

  /**
   * @notice Returns the funding duration
   * @return uint256 the funding duration
   **/
  function fundingDuration() external view returns (uint256);

  /**
   * @notice Returns the funding rate for a specified epoch
   * @param  _epoch The epoch to get the funding rate for
   * @return uint256 the funding rate
   **/
  function fundingRates(uint256 _epoch) external view returns (uint256);

  /**
   * @notice Returns the price of the underlying in ETH in 1e8 precision
   * @return uint256 the current underlying price
   **/
  function getUnderlyingPrice() external view returns (uint256);

  /**
   * @notice Returns the volatility from the volatility oracle
   * @param  _strike Strike of the option
   * @return uint256 Volatility for given strike
   **/
  function getVolatility(uint256 _strike) external view returns (uint256);

  /**
   * @notice Calculate premium for an option
   * @param  _strike Strike price of the option
   * @param  _amount Amount of options (1e18 precision)
   * @param  timeToExpiry Time to expiry of the option in seconds
   * @param  _price in 1e8 precision
   * @return premium in collateralToken in collateral precision
   **/
  function calculatePremium(
    uint256 _strike,
    uint256 _amount,
    uint256 timeToExpiry,
    uint256 _price
  ) external view returns (uint256 premium);

  /**
   * @notice Calculate Pnl
   * @param  price price of the underlying asset
   * @param  strike strike price of the option
   * @param  amount amount of options
   * @return uint256 the PnL calculated
   **/
  function calculatePnl(
    uint256 price,
    uint256 strike,
    uint256 amount
  ) external pure returns (uint256);

  /**
   * @notice Get the timestamp for next funding payment
   * @dev    Calculates funding timestamp based on genesis timestamp from deployment,
   *         the preset fundingDuration, and the current pointer
   * @return timestamp the next funding timestamp
   **/
  function nextFundingPaymentTimestamp()
    external
    view
    returns (uint256 timestamp);

  /**
   * @dev Function to round up a value to the roundingPrecision.
   * @param _strike the strike
   * @return strike rounded up to the nearest roundingPrecision
   **/
  function roundUp(uint256 _strike) external view returns (uint256 strike);

  /// @dev the pointer to the lattest funding payment timestamp
  function latestFundingPaymentPointer() external view returns (uint256);

  // ================================ TREASURY FUNCTIONS ================================ //

  /**
   * @notice Purchases options for the current epoch
   * @param  amount Amount of options to purchase
   * @param  to address to send the purchased options to
   **/
  function purchase(
    uint256 amount,
    address to
  ) external returns (uint256 premium, uint256 tokenId);

  /** 
  * @notice   The function asset settles the options by transferring rdpx 
              from the rdpxV2Core and transfers eth to the rdpx rdpxV2Core 
              contract at the option strike price. Will also the burn the 
              option tokens from the user.
  * @param    optionIds The Ids of the option to settle
  * @return   ethAmount The amount of eth transferred to the rdpx rdpxV2Core
  * @return   rdpxAmount The amount of rdpx transferred from the rdpx rdpxV2Core
  **/
  function settle(
    uint256[] memory optionIds
  ) external returns (uint256, uint256);

  /**
   * @notice function for rdpxV2Core to pay funding to option writers
   * @return uint256 the total funding for the ongoing epoch
   **/
  function payFunding() external returns (uint256);

  /**
   * @notice function to transfer funding into the LP in a drip-vested manner
   * @dev    addProceeds() is invoked to update totalCollateral in LP
   **/
  function updateFunding() external;

  /*==== EVENTS ====*/

  /// @notice Emitted when addresses are set
  /// @param addresses The Addresses struct
  event AddressesSet(Addresses addresses);

  /// @notice Emitted when funds are withdrawn in an emergency
  /// @param sender msg.sender
  /// @param tokens Array of tokens that were withdrawn
  event EmergencyWithdraw(address sender, address[] tokens);

  /// @notice Emitted when a purchase is made on the vault by the rdpxV2Core
  /// @param strike The strike of the option
  /// @param amount The amount of options purchased
  /// @param premium The premium paid by the rdpxV2Core
  /// @param to Address the options were sent to
  /// @param sender Address of the rdpxV2Core
  event Purchase(
    uint256 strike,
    uint256 amount,
    uint256 premium,
    address indexed to,
    address indexed sender
  );

  /// @notice Emitted on when settle is called by the rdpxV2Core
  /// @param ethAmount Amount of ETH received by the rdpxV2Core
  /// @param rdpxAmount Amount of rDPX received by the rdpxV2Core
  /// @param tokenIds Array of token ids that were settled
  event Settle(uint256 ethAmount, uint256 rdpxAmount, uint256[] tokenIds);

  /// @notice Emitted when funding is paid
  /// @param sender msg.sender
  /// @param amount amount paid
  /// @param latestFundingPaymentPointer latest funding payment pointer
  event PayFunding(
    address sender,
    uint256 amount,
    uint256 latestFundingPaymentPointer
  );

  /// @notice Emitted when calculate funding is called
  /// @param sender msg.sender
  /// @param amount amount of options
  /// @param strike strike of the option
  /// @param fundingAmount funding amount
  /// @param latestFundingPaymentPointer latest funding payment pointer
  event CalculateFunding(
    address sender,
    uint256 amount,
    uint256 strike,
    uint256 fundingAmount,
    uint256 latestFundingPaymentPointer
  );

  /// @notice Emitted when funding paymentPointer is updated
  /// @param latestFundingPaymentPointer latest funding payment pointer
  event FundingPaymentPointerUpdated(uint256 latestFundingPaymentPointer);

  /// @notice Emitted when funding is paid
  /// @param sender msg.sender
  /// @param amount amount paid
  /// @param latestFundingPaymentPointer latest funding payment pointer
  event FundingPaid(
    address sender,
    uint256 amount,
    uint256 latestFundingPaymentPointer
  );

  /*==== STRUCTS ====*/

  /// @dev Struct of all addresses used by the vault
  struct Addresses {
    address optionPricing;
    address assetPriceOracle;
    address volatilityOracle;
    address feeDistributor;
    address rdpx;
    address perpetualAtlanticVaultLP;
    address rdpxV2Core;
  }

  /// @dev Struct of a option position
  struct OptionPosition {
    uint256 strike;
    uint256 amount;
    uint256 positionId;
  }
}
"},"contracts/perp-vault/IPerpetualAtlanticVaultLP.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

interface IPerpetualAtlanticVaultLP {
  /// @notice Returns the total available collateral to buy options
  function totalAvailableCollateral() external view returns (uint256);

  /// @notice Locks collateral
  /// @param amount Amount of collateral to lock
  function lockCollateral(uint256 amount) external;

  /// @notice Unlocks collateral
  /// @param amount Amount of collateral to unlock
  function unlockLiquidity(uint256 amount) external;

  /// @notice Adds premium and fees to total available assets
  /// @param proceeds amount of proceeds to add
  function addProceeds(uint256 proceeds) external;

  /// @notice Subtract loss from total available assets
  /// @param loss amount of loss to subtract
  function subtractLoss(uint256 loss) external;

  /// @notice Adds rDPX to the vault shares
  /// @param amount of rDPX to add
  function addRdpx(uint256 amount) external;
}
"},"contracts/perp-vault/PerpetualAtlanticVault.sol":{"content":"//SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

// Libraries
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// Contracts
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import { ERC721Enumerable } from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import { ERC721Burnable } from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Burnable.sol";
import { ERC4626 } from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { Counters } from "@openzeppelin/contracts/utils/Counters.sol";
import { IPerpetualAtlanticVaultLP } from "./IPerpetualAtlanticVaultLP.sol";
import { ContractWhitelist } from "../helper/ContractWhitelist.sol";
import { Pausable } from "../helper/Pausable.sol";

// Interfaces
import { IPerpetualAtlanticVault } from "./IPerpetualAtlanticVault.sol";
import { IERC20WithBurn } from "../interfaces/IERC20WithBurn.sol";
import { IOptionPricing } from "../interfaces/IOptionPricing.sol";
import { IRdpxEthOracle } from "../interfaces/IRdpxEthOracle.sol";
import { IVolatilityOracle } from "../interfaces/IVolatilityOracle.sol";

/// @title Contract to offer perpetual atlantic rDPX PUT options to the rdpxV2Core contract
/// @dev Option tokens are in erc20 18 decimals & Strikes are in 1e8 precision
contract PerpetualAtlanticVault is
  IPerpetualAtlanticVault,
  ReentrancyGuard,
  Pausable,
  ERC721,
  ERC721Enumerable,
  ERC721Burnable,
  AccessControl,
  ContractWhitelist
{
  using SafeERC20 for IERC20WithBurn;
  using Counters for Counters.Counter;

  /// @dev Token ID counter for write positions
  Counters.Counter private _tokenIdCounter;

  /// @dev Manager role which handles bootstrapping
  bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

  /// @dev Rdpx v2 core role which can purchase and settle options
  bytes32 public constant RDPXV2CORE_ROLE = keccak256("RDPXV2CORE_ROLE");

  /// @dev Underlying assets symbol
  string public underlyingSymbol;

  /// @dev Contract addresses
  Addresses public addresses;

  /// @dev Collateral Token
  IERC20WithBurn public collateralToken;

  /// @dev The precision of the collateral token
  uint256 public collateralPrecision;

  /// @dev tokenId => OptionPosition
  mapping(uint256 => OptionPosition) public optionPositions;

  /// @dev number of options funding has been accounted for the epoch
  mapping(uint256 => uint256) public fundingPaymentsAccountedFor;

  /// @dev the funding accounted for the epoch and strike
  mapping(uint256 => mapping(uint256 => uint256))
    public fundingPaymentsAccountedForPerStrike;

  /// @dev the total funding for the epoch
  mapping(uint256 => uint256) public totalFundingForEpoch;

  /// @dev amount of options per strike
  mapping(uint256 => uint256) public optionsPerStrike;

  /// @dev latest funding update per strike
  mapping(uint256 => uint256) public latestFundingPerStrike;

  // @dev Funding rate for the epoch
  mapping(uint256 => uint256) public fundingRates;

  /// @dev the pointer to the lattest funding payment timestamp
  /// @notice Explain to an end user what this does
  /// @dev Explain to a developer any extra details
  /// @return Documents the return variables of a contract’s function state variable
  /// @inheritdoc	IPerpetualAtlanticVault
  uint256 public latestFundingPaymentPointer = 0;

  /// @dev the total number of active options
  uint256 public totalActiveOptions;

  /// @dev genesis timestamp
  uint256 public genesis;

  /// @dev the timestamp of the last update where funding was paid for
  uint256 public lastUpdateTime;

  /// @dev the duration between funding payments
  uint256 public fundingDuration = 7 days;

  /// @dev the precision to round up to
  uint256 public roundingPrecision = 1e6;

  // ================================ CONSTRUCTOR ================================ //

  /// @notice Contract constructor
  /// @param _name ERC721 name
  /// @param _symbol ERC721 symbol
  /// @param _collateralToken Collateral token of the perpetual atlantic vault
  /// @param _gensis Gensis time for funding calculation
  constructor(
    string memory _name,
    string memory _symbol,
    address _collateralToken,
    uint256 _gensis
  ) ERC721(_name, _symbol) {
    _validate(_collateralToken != address(0), 1);

    collateralToken = IERC20WithBurn(_collateralToken);
    underlyingSymbol = collateralToken.symbol();
    collateralPrecision = 10 ** collateralToken.decimals();
    genesis = _gensis;

    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    _setupRole(MANAGER_ROLE, msg.sender);
  }

  // ================================ ADMIN FUNCTIONS ================================ //

  /**
   * @notice Pauses the vault for emergency cases
   * @dev    Can only be called by the owner
   **/
  function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
    _pause();
  }

  /**
   * @notice Unpauses the vault
   * @dev    Can only be called by the owner
   **/
  function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
    _unpause();
  }

  /**
   * @notice Add a contract to the whitelist
   * @dev    Can only be called by the owner
   * @param  _contract Address of the contract that needs to be added to the whitelist
   **/
  function addToContractWhitelist(
    address _contract
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    _addToContractWhitelist(_contract);
  }

  /**
   * @notice Remove a contract to the whitelist
   * @dev    Can only be called by the owner
   * @param  _contract Address of the contract that needs to be removed from the whitelist
   **/
  function removeFromContractWhitelist(
    address _contract
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    _removeFromContractWhitelist(_contract);
  }

  /**
   * @notice Sets (adds) a list of addresses to the address list
   * @dev    Can only be called by the owner
   * @param  _optionPricing Address of the option pricing contract
   * @param  _assetPriceOracle Address of the asset price oracle contract
   * @param  _volatilityOracle Address of the volatility oracle contract
   * @param  _feeDistributor Address of the fee distributor contract
   * @param  _rdpx Address of the rdpx contract
   * @param  _perpetualAtlanticVaultLP Address of the perpetual atlantic vault lp contract
   * @param  _rdpxV2Core Address of the rdpx v2 rdpxV2Core contract
   **/
  function setAddresses(
    address _optionPricing,
    address _assetPriceOracle,
    address _volatilityOracle,
    address _feeDistributor,
    address _rdpx,
    address _perpetualAtlanticVaultLP,
    address _rdpxV2Core
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    _validate(_optionPricing != address(0), 1);
    _validate(_assetPriceOracle != address(0), 1);
    _validate(_volatilityOracle != address(0), 1);
    _validate(_feeDistributor != address(0), 1);
    _validate(_rdpx != address(0), 1);
    _validate(_perpetualAtlanticVaultLP != address(0), 1);
    _validate(_rdpxV2Core != address(0), 1);

    addresses = Addresses({
      optionPricing: _optionPricing,
      assetPriceOracle: _assetPriceOracle,
      volatilityOracle: _volatilityOracle,
      feeDistributor: _feeDistributor,
      rdpx: _rdpx,
      perpetualAtlanticVaultLP: _perpetualAtlanticVaultLP,
      rdpxV2Core: _rdpxV2Core
    });
    collateralToken.safeApprove(
      addresses.perpetualAtlanticVaultLP,
      type(uint256).max
    );
    emit AddressesSet(addresses);
  }

  /**
   * @notice Transfers all funds to msg.sender
   * @dev    Can only be called by the owner
   * @param  tokens The list of erc20 tokens to withdraw
   **/
  function emergencyWithdraw(
    address[] calldata tokens
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    _whenPaused();
    IERC20WithBurn token;

    for (uint256 i = 0; i < tokens.length; i++) {
      token = IERC20WithBurn(tokens[i]);
      token.safeTransfer(msg.sender, token.balanceOf(address(this)));
    }

    emit EmergencyWithdraw(msg.sender, tokens);
  }

  /**
   * @notice Updates the funding duration
   * @dev    Can only be called by the owner
   **/
  function updateFundingDuration(
    uint256 _fundingDuration
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    fundingDuration = _fundingDuration;
  }

  function setLpAllowance(bool increase) external onlyRole(DEFAULT_ADMIN_ROLE) {
    increase
      ? collateralToken.approve(
        addresses.perpetualAtlanticVaultLP,
        type(uint256).max
      )
      : collateralToken.approve(addresses.perpetualAtlanticVaultLP, 0);
  }

  // ================================ TREASURY FUNCTIONS ================================ //

  /// @inheritdoc	IPerpetualAtlanticVault
  function purchase(
    uint256 amount,
    address to
  )
    external
    nonReentrant
    onlyRole(RDPXV2CORE_ROLE)
    returns (uint256 premium, uint256 tokenId)
  {
    _whenNotPaused();
    _validate(amount > 0, 2);

    updateFunding();

    uint256 currentPrice = getUnderlyingPrice(); // price of underlying wrt collateralToken
    uint256 strike = roundUp(currentPrice - (currentPrice / 4)); // 25% below the current price
    IPerpetualAtlanticVaultLP perpetualAtlanticVaultLp = IPerpetualAtlanticVaultLP(
        addresses.perpetualAtlanticVaultLP
      );

    // Check if vault has enough collateral to write the options
    uint256 requiredCollateral = (amount * strike) / 1e8;

    _validate(
      requiredCollateral <= perpetualAtlanticVaultLp.totalAvailableCollateral(),
      3
    );

    uint256 timeToExpiry = nextFundingPaymentTimestamp() - block.timestamp;

    // Get total premium for all options being purchased
    premium = calculatePremium(strike, amount, timeToExpiry, 0);

    // Transfer premium from msg.sender to PerpetualAtlantics vault
    collateralToken.safeTransferFrom(msg.sender, address(this), premium);

    perpetualAtlanticVaultLp.lockCollateral(requiredCollateral);
    _updateFundingRate(premium);

    // Mint the option tokens
    tokenId = _mintOptionToken();
    optionPositions[tokenId] = OptionPosition({
      strike: strike,
      amount: amount,
      positionId: tokenId
    });

    totalActiveOptions += amount;
    fundingPaymentsAccountedFor[latestFundingPaymentPointer] += amount;
    optionsPerStrike[strike] += amount;

    // record the number of options funding has been accounted for the epoch and strike
    fundingPaymentsAccountedForPerStrike[latestFundingPaymentPointer][
      strike
    ] += amount;

    emit Purchase(strike, amount, premium, to, msg.sender);
  }

  /// @inheritdoc	IPerpetualAtlanticVault
  function settle(
    uint256[] memory optionIds
  )
    external
    nonReentrant
    onlyRole(RDPXV2CORE_ROLE)
    returns (uint256 ethAmount, uint256 rdpxAmount)
  {
    _whenNotPaused();
    _isEligibleSender();

    updateFunding();

    for (uint256 i = 0; i < optionIds.length; i++) {
      uint256 strike = optionPositions[optionIds[i]].strike;
      uint256 amount = optionPositions[optionIds[i]].amount;

      // check if strike is ITM
      _validate(strike >= getUnderlyingPrice(), 7);

      ethAmount += (amount * strike) / 1e8;
      rdpxAmount += amount;
      optionsPerStrike[strike] -= amount;
      totalActiveOptions -= amount;

      // Burn option tokens from user
      _burn(optionIds[i]);

      optionPositions[optionIds[i]].strike = 0;
    }

    // Transfer collateral token from perpetual vault to rdpx rdpxV2Core
    collateralToken.safeTransferFrom(
      addresses.perpetualAtlanticVaultLP,
      addresses.rdpxV2Core,
      ethAmount
    );
    // Transfer rdpx from rdpx rdpxV2Core to perpetual vault
    IERC20WithBurn(addresses.rdpx).safeTransferFrom(
      addresses.rdpxV2Core,
      addresses.perpetualAtlanticVaultLP,
      rdpxAmount
    );

    IPerpetualAtlanticVaultLP(addresses.perpetualAtlanticVaultLP).subtractLoss(
      ethAmount
    );
    IPerpetualAtlanticVaultLP(addresses.perpetualAtlanticVaultLP)
      .unlockLiquidity(ethAmount);
    IPerpetualAtlanticVaultLP(addresses.perpetualAtlanticVaultLP).addRdpx(
      rdpxAmount
    );

    emit Settle(ethAmount, rdpxAmount, optionIds);
  }

  /// @inheritdoc	IPerpetualAtlanticVault
  function payFunding() external onlyRole(RDPXV2CORE_ROLE) returns (uint256) {
    _whenNotPaused();
    _isEligibleSender();

    _validate(
      totalActiveOptions ==
        fundingPaymentsAccountedFor[latestFundingPaymentPointer],
      6
    );

    collateralToken.safeTransferFrom(
      addresses.rdpxV2Core,
      address(this),
      totalFundingForEpoch[latestFundingPaymentPointer]
    );
    _updateFundingRate(totalFundingForEpoch[latestFundingPaymentPointer]);

    emit PayFunding(
      msg.sender,
      totalFundingForEpoch[latestFundingPaymentPointer],
      latestFundingPaymentPointer
    );

    return (totalFundingForEpoch[latestFundingPaymentPointer]);
  }

  // ================================ PUBLIC/EXTERNAL FUNCTIONS ================================ //

  /**
   * @notice Function to calculate the funding of options for the next epoch
   * @param  strikes array of strikes to calculate the funding for
   * @return fundingAmount the funding of options
   **/
  function calculateFunding(
    uint256[] memory strikes
  ) external nonReentrant returns (uint256 fundingAmount) {
    _whenNotPaused();
    _isEligibleSender();

    updateFundingPaymentPointer();

    for (uint256 i = 0; i < strikes.length; i++) {
      _validate(optionsPerStrike[strikes[i]] > 0, 4);
      _validate(
        latestFundingPerStrike[strikes[i]] != latestFundingPaymentPointer,
        5
      );
      uint256 strike = strikes[i];

      uint256 amount = optionsPerStrike[strike] -
        fundingPaymentsAccountedForPerStrike[latestFundingPaymentPointer][
          strike
        ];

      uint256 timeToExpiry = nextFundingPaymentTimestamp() -
        (genesis + ((latestFundingPaymentPointer - 1) * fundingDuration));

      uint256 premium = calculatePremium(
        strike,
        amount,
        timeToExpiry,
        getUnderlyingPrice()
      );

      latestFundingPerStrike[strike] = latestFundingPaymentPointer;
      fundingAmount += premium;

      // Record number of options that funding payments were accounted for, for this epoch
      fundingPaymentsAccountedFor[latestFundingPaymentPointer] += amount;

      // record the number of options funding has been accounted for the epoch and strike
      fundingPaymentsAccountedForPerStrike[latestFundingPaymentPointer][
        strike
      ] += amount;

      // Record total funding for this epoch
      // This does not need to be done in purchase() since it's already accounted for using `addProceeds()`
      totalFundingForEpoch[latestFundingPaymentPointer] += premium;

      emit CalculateFunding(
        msg.sender,
        amount,
        strike,
        premium,
        latestFundingPaymentPointer
      );
    }
  }

  /// @dev Helper function that updates the latest funding payment pointer based on current timestamp
  function updateFundingPaymentPointer() public {
    while (block.timestamp >= nextFundingPaymentTimestamp()) {
      if (lastUpdateTime < nextFundingPaymentTimestamp()) {
        uint256 currentFundingRate = fundingRates[latestFundingPaymentPointer];

        uint256 startTime = lastUpdateTime == 0
          ? (nextFundingPaymentTimestamp() - fundingDuration)
          : lastUpdateTime;

        lastUpdateTime = nextFundingPaymentTimestamp();

        collateralToken.safeTransfer(
          addresses.perpetualAtlanticVaultLP,
          (currentFundingRate * (nextFundingPaymentTimestamp() - startTime)) /
            1e18
        );

        IPerpetualAtlanticVaultLP(addresses.perpetualAtlanticVaultLP)
          .addProceeds(
            (currentFundingRate * (nextFundingPaymentTimestamp() - startTime)) /
              1e18
          );

        emit FundingPaid(
          msg.sender,
          ((currentFundingRate * (nextFundingPaymentTimestamp() - startTime)) /
            1e18),
          latestFundingPaymentPointer
        );
      }

      latestFundingPaymentPointer += 1;
      emit FundingPaymentPointerUpdated(latestFundingPaymentPointer);
    }
  }

  /**
   * @notice function to transfer funding into the LP in a drip-vested manner
   * @dev    addProceeds() is invoked to update totalCollateral in LP
   **/
  function updateFunding() public {
    updateFundingPaymentPointer();
    uint256 currentFundingRate = fundingRates[latestFundingPaymentPointer];
    uint256 startTime = lastUpdateTime == 0
      ? (nextFundingPaymentTimestamp() - fundingDuration)
      : lastUpdateTime;
    lastUpdateTime = block.timestamp;

    collateralToken.safeTransfer(
      addresses.perpetualAtlanticVaultLP,
      (currentFundingRate * (block.timestamp - startTime)) / 1e18
    );

    IPerpetualAtlanticVaultLP(addresses.perpetualAtlanticVaultLP).addProceeds(
      (currentFundingRate * (block.timestamp - startTime)) / 1e18
    );

    emit FundingPaid(
      msg.sender,
      ((currentFundingRate * (block.timestamp - startTime)) / 1e18),
      latestFundingPaymentPointer
    );
  }

  // ================================ VIEWS ================================ //

  /// @inheritdoc	IPerpetualAtlanticVault
  function getUnderlyingPrice() public view returns (uint256) {
    return IRdpxEthOracle(addresses.assetPriceOracle).getRdpxPriceInEth();
  }

  /// @inheritdoc	IPerpetualAtlanticVault
  function getVolatility(uint256 _strike) public view returns (uint256) {
    return IVolatilityOracle(addresses.volatilityOracle).getVolatility(_strike);
  }

  /// @inheritdoc	IPerpetualAtlanticVault
  function calculatePremium(
    uint256 _strike,
    uint256 _amount,
    uint256 timeToExpiry,
    uint256 _price
  ) public view returns (uint256 premium) {
    premium = ((IOptionPricing(addresses.optionPricing).getOptionPrice(
      _strike,
      _price > 0 ? _price : getUnderlyingPrice(),
      getVolatility(_strike),
      timeToExpiry
    ) * _amount) / 1e8);
  }

  /// @inheritdoc	IPerpetualAtlanticVault
  function calculatePnl(
    uint256 price,
    uint256 strike,
    uint256 amount
  ) public pure returns (uint256) {
    return strike > price ? ((strike - price) * amount) / 1e8 : 0;
  }

  /// @inheritdoc	IPerpetualAtlanticVault
  function nextFundingPaymentTimestamp()
    public
    view
    returns (uint256 timestamp)
  {
    return genesis + (latestFundingPaymentPointer * fundingDuration);
  }

  /**
   * @dev Function to round up a value to the roundingPrecision.
   * @param _strike the strike
   * @return strike rounded up to the nearest roundingPrecision
   **/
  function roundUp(uint256 _strike) public view returns (uint256 strike) {
    uint256 remainder = _strike % roundingPrecision;
    if (remainder == 0) {
      return _strike;
    } else {
      return _strike - remainder + roundingPrecision;
    }
  }

  // ================================ PRIVATE/HELPER FUNCTIONS ================================ //

  /// @dev Internal function to mint a option token
  function _mintOptionToken() private returns (uint256 tokenId) {
    tokenId = _tokenIdCounter.current();
    _tokenIdCounter.increment();
    _mint(addresses.rdpxV2Core, tokenId);
  }

  function _updateFundingRate(uint256 amount) private {
    if (fundingRates[latestFundingPaymentPointer] == 0) {
      uint256 startTime;
      if (lastUpdateTime > nextFundingPaymentTimestamp() - fundingDuration) {
        startTime = lastUpdateTime;
      } else {
        startTime = nextFundingPaymentTimestamp() - fundingDuration;
      }
      uint256 endTime = nextFundingPaymentTimestamp();
      fundingRates[latestFundingPaymentPointer] =
        (amount * 1e18) /
        (endTime - startTime);
    } else {
      uint256 startTime = lastUpdateTime;
      uint256 endTime = nextFundingPaymentTimestamp();
      if (endTime == startTime) return;
      fundingRates[latestFundingPaymentPointer] =
        fundingRates[latestFundingPaymentPointer] +
        ((amount * 1e18) / (endTime - startTime));
    }
  }

  /**
   * @dev    internal function to validate checks
   * @param  _clause the boolean clause to validate
   * @param  _errorCode error code for error mapping below
   **/
  function _validate(bool _clause, uint256 _errorCode) private pure {
    if (!_clause) revert PerpetualAtlanticVaultError(_errorCode);
  }

  // ================================ ERRORS ================================ //

  /**
   * @dev  Custom Error used to validate checks within the contract's functions.
   *       The uint256 error code corresponds to an error message.
   **/
  error PerpetualAtlanticVaultError(uint256);

  // ================================ Solidity Required Overrides ================================ //

  function _beforeTokenTransfer(
    address from,
    address to,
    uint256 tokenId,
    uint256 batchSize
  ) internal override(ERC721, ERC721Enumerable) {
    _whenNotPaused();
    super._beforeTokenTransfer(from, to, tokenId, batchSize);
  }

  function supportsInterface(
    bytes4 interfaceId
  )
    public
    view
    override(ERC721, ERC721Enumerable, AccessControl)
    returns (bool)
  {
    return super.supportsInterface(interfaceId);
  }
}

// ERROR CODES
// E1: "Zero address",
// E2: "Amount must be greater than 0",
// E3: "Insufficient collateral for purchase",
// E4: "No options for strike",
// E5: "Option strike already funded",
// E6: "All funding payments must be accounted for",
// E7: "Option is not ITM"
"},"contracts/perp-vault/PerpetualAtlanticVaultLP.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

// Contracts
import { ERC20 } from "solmate/src/tokens/ERC20.sol";
import { FixedPointMathLib } from "solmate/src/utils/FixedPointMathLib.sol";
import { IERC20WithBurn } from "../interfaces/IERC20WithBurn.sol";

// Libraries
import { Strings } from "@openzeppelin/contracts/utils/Strings.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SafeTransferLib } from "solmate/src/utils/SafeTransferLib.sol";

// Interfaces
import { IPerpetualAtlanticVault } from "./IPerpetualAtlanticVault.sol";
import { IPerpetualAtlanticVaultLP } from "./IPerpetualAtlanticVaultLP.sol";

/**
 * @title PerpetaulAtlanticVault LP Token
 */
contract PerpetualAtlanticVaultLP is ERC20, IPerpetualAtlanticVaultLP {
  using SafeERC20 for IERC20WithBurn;
  using SafeTransferLib for ERC20;
  using FixedPointMathLib for uint256;

  // ================================ EVENTS ================================ //

  event Deposit(
    address indexed caller,
    address indexed owner,
    uint256 assets,
    uint256 shares
  );

  event Withdraw(
    address indexed caller,
    address indexed receiver,
    address indexed owner,
    uint256 assets,
    uint256 shares
  );

  // ================================ STATE VARIABLES ================================ //

  /// @dev The address of the perpetual Atlantic Vault contract creating the lp token
  IPerpetualAtlanticVault public perpetualAtlanticVault;

  /// @dev The collateral token
  ERC20 public collateral;

  /// @dev The symbol reperesenting the underlying asset of the perpetualatlanticvault lp
  string public underlyingSymbol;

  /// @dev The symbol representing the collateral token of the perpetualatlanticvault lp
  string public collateralSymbol;

  /// @dev Total collateral available
  uint256 private _totalCollateral;

  /// @dev Active collateral
  uint256 private _activeCollateral;

  /// @dev Total rdpx available
  uint256 private _rdpxCollateral;

  /// @dev address of rdpx token
  address public rdpx;

  /// @dev address of the rdpx rdpxV2Core contract
  address public rdpxRdpxV2Core;

  // ================================ CONSTRUCTOR ================================ //

  /**
   * @param _perpetualAtlanticVault The address of the perpetual atlantic vault contract creating the lp token
   * @param _rdpxRdpxV2Core The address of the rdpx rdpxV2Core contract
   * @param _collateral The address of the collateral asset in the perpetualatlanticvault contract
   * @param _collateralSymbol The symbol of the collateral asset token
   * @param _rdpx The address of the rdpx token
   */
  constructor(
    address _perpetualAtlanticVault,
    address _rdpxRdpxV2Core,
    address _collateral,
    address _rdpx,
    string memory _collateralSymbol
  )
    ERC20(
      "PerpetualAtlanticVault LP Token",
      _collateralSymbol,
      ERC20(_collateral).decimals()
    )
  {
    require(
      _perpetualAtlanticVault != address(0) || _rdpx != address(0),
      "ZERO_ADDRESS"
    );
    perpetualAtlanticVault = IPerpetualAtlanticVault(_perpetualAtlanticVault);
    rdpxRdpxV2Core = _rdpxRdpxV2Core;
    collateralSymbol = _collateralSymbol;
    rdpx = _rdpx;
    collateral = ERC20(_collateral);

    symbol = string.concat(_collateralSymbol, "-LP");

    collateral.approve(_perpetualAtlanticVault, type(uint256).max);
    ERC20(rdpx).approve(_perpetualAtlanticVault, type(uint256).max);
  }

  // ================================ PUBLIC FUNCTIONS ================================ //

  /**
   * @notice deposit into ERC4626 token
   * @param assets assets
   * @param receiver receiver
   * @return shares shares of LP tokens minted
   */
  function deposit(
    uint256 assets,
    address receiver
  ) public virtual returns (uint256 shares) {
    // Check for rounding error since we round down in previewDeposit.
    require((shares = previewDeposit(assets)) != 0, "ZERO_SHARES");

    perpetualAtlanticVault.updateFunding();

    // Need to transfer before minting or ERC777s could reenter.
    collateral.transferFrom(msg.sender, address(this), assets);

    _mint(receiver, shares);

    _totalCollateral += assets;

    emit Deposit(msg.sender, receiver, assets, shares);
  }

  /**
   * @notice redeem ERC4626 token
   * @param shares shares
   * @param receiver receiver
   * @param owner owner
   * @return assets native tokens to be received
   * @return rdpxAmount rdpx tokens to be received
   */
  function redeem(
    uint256 shares,
    address receiver,
    address owner
  ) public returns (uint256 assets, uint256 rdpxAmount) {
    perpetualAtlanticVault.updateFunding();

    if (msg.sender != owner) {
      uint256 allowed = allowance[owner][msg.sender]; // Saves gas for limited approvals.

      if (allowed != type(uint256).max) {
        allowance[owner][msg.sender] = allowed - shares;
      }
    }
    (assets, rdpxAmount) = redeemPreview(shares);

    // Check for rounding error since we round down in previewRedeem.
    require(assets != 0, "ZERO_ASSETS");

    _rdpxCollateral -= rdpxAmount;

    beforeWithdraw(assets, shares);

    _burn(owner, shares);

    collateral.transfer(receiver, assets);

    IERC20WithBurn(rdpx).safeTransfer(receiver, rdpxAmount);

    emit Withdraw(msg.sender, receiver, owner, assets, shares);
  }

  // ================================ PERP VAULT FUNCTIONS ================================ //

  /// @inheritdoc	IPerpetualAtlanticVaultLP
  function lockCollateral(uint256 amount) public onlyPerpVault {
    _activeCollateral += amount;
  }

  /// @inheritdoc	IPerpetualAtlanticVaultLP
  function unlockLiquidity(uint256 amount) public onlyPerpVault {
    _activeCollateral -= amount;
  }

  /// @inheritdoc	IPerpetualAtlanticVaultLP
  function addProceeds(uint256 proceeds) public onlyPerpVault {
    require(
      collateral.balanceOf(address(this)) >= _totalCollateral + proceeds,
      "Not enough collateral token was sent"
    );
    _totalCollateral += proceeds;
  }

  /// @inheritdoc	IPerpetualAtlanticVaultLP
  function subtractLoss(uint256 loss) public onlyPerpVault {
    require(
      collateral.balanceOf(address(this)) == _totalCollateral - loss,
      "Not enough collateral was sent out"
    );
    _totalCollateral -= loss;
  }

  /// @inheritdoc	IPerpetualAtlanticVaultLP
  function addRdpx(uint256 amount) public onlyPerpVault {
    require(
      IERC20WithBurn(rdpx).balanceOf(address(this)) >= _rdpxCollateral + amount,
      "Not enough rdpx token was sent"
    );
    _rdpxCollateral += amount;
  }

  // ================================ INTERNAL FUNCTUONS ================================ //

  function _convertToAssets(
    uint256 shares
  ) internal view virtual returns (uint256 assets, uint256 rdpxAmount) {
    uint256 supply = totalSupply;
    return
      (supply == 0)
        ? (shares, 0)
        : (
          shares.mulDivDown(totalCollateral(), supply),
          shares.mulDivDown(_rdpxCollateral, supply)
        );
  }

  function _beforeTokenTransfer(
    address from,
    address,
    uint256
  ) internal virtual {}

  // ================================ VIEWS ================================ //

  /// @notice Returns the total active collateral
  function activeCollateral() public view returns (uint256) {
    return _activeCollateral;
  }

  /// @notice Returns the total collateral
  function totalCollateral() public view returns (uint256) {
    return _totalCollateral;
  }

  /// @notice Returns the total rdpx collateral
  function rdpxCollateral() public view returns (uint256) {
    return _rdpxCollateral;
  }

  /// @notice Returns the total available collateral
  function totalAvailableCollateral() public view returns (uint256) {
    return _totalCollateral - _activeCollateral;
  }

  // ================================ PUBLIC VIEW FUNCTIONS ================================ //

  /// @notice Returns the amount of collateral and rdpx per share
  function redeemPreview(
    uint256 shares
  ) public view returns (uint256, uint256) {
    return _convertToAssets(shares);
  }

  /// @notice Returns the amount of shares recieved for a given amount of assets
  function previewDeposit(uint256 assets) public view returns (uint256) {
    return convertToShares(assets);
  }

  /// @notice Returns the amount of shares recieved for a given amount of assets
  function convertToShares(
    uint256 assets
  ) public view returns (uint256 shares) {
    uint256 supply = totalSupply;
    uint256 rdpxPriceInAlphaToken = perpetualAtlanticVault.getUnderlyingPrice();

    uint256 totalVaultCollateral = totalCollateral() +
      ((_rdpxCollateral * rdpxPriceInAlphaToken) / 1e8);
    return
      supply == 0 ? assets : assets.mulDivDown(supply, totalVaultCollateral);
  }

  function beforeWithdraw(uint256 assets, uint256 /*shares*/) internal {
    require(
      assets <= totalAvailableCollateral(),
      "Not enough available assets to satisfy withdrawal"
    );
    _totalCollateral -= assets;
  }

  // ================================ MODIFIERS ================================ //
  modifier onlyPerpVault() {
    require(
      msg.sender == address(perpetualAtlanticVault),
      "Only the perp vault can call this function"
    );
    _;
  }
}
"},"contracts/reLP/ReLPContract.sol":{"content":"//SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.19;

// Contracts
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { SafeMath } from "@openzeppelin/contracts/utils/math/SafeMath.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// Interfaces
import { IERC20WithBurn } from "../interfaces/IERC20WithBurn.sol";
import { IUniswapV2Router } from "../uniswap_V2/IUniswapV2Router.sol";
import { IUniswapV2Pair } from "../uniswap_V2/IUniswapV2Pair.sol";
import { IRdpxReserve } from "../reserve/IRdpxReserve.sol";
import { IRdpxEthOracle } from "../interfaces/IRdpxEthOracle.sol";
import { IRdpxV2Core } from "../core/IRdpxV2Core.sol";
import { IUniV2LiquidityAmo } from "../interfaces/IUniV2LiquidityAmo.sol";

// Libraries
import { UniswapV2Library } from "../uniswap_V2/libraries/UniswapV2Library.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title reLP contract
/// @author Dopex
/// @notice The reLP contract is a contract that ReLP's liquidity
contract ReLPContract is AccessControl {
  using SafeERC20 for IERC20WithBurn;
  using SafeMath for uint256;

  // ================================ STATE VARIABLES ================================ //
  struct Addresses {
    // token A address
    address tokenA; // rdpx
    // token B address
    address tokenB; // weth
    // pair address
    address pair;
    // rdpxV2Core address
    address rdpxV2Core;
    // tokenA reserve address
    address tokenAReserve;
    // amo address
    address amo;
    // rdpx price oracle
    address rdpxOracle;
    // AMM Factory
    address ammFactory;
    // AMM Router
    address ammRouter;
  }

  struct TokenAInfo {
    // tokenA reserves
    uint256 tokenAReserve;
    // rdpx price
    uint256 tokenAPrice;
    // tokenA LP reserves
    uint256 tokenALpReserve;
  }

  /// @notice  addresses of the contracts
  Addresses public addresses;

  /// @notice reLP factor
  uint256 public reLPFactor;

  /// @notice Precision used for prices, percentages and other calculations
  uint256 public constant DEFAULT_PRECISION = 1e8;

  /// @notice rdpxV2Core role
  bytes32 public constant RDPXV2CORE_ROLE = keccak256("RDPXV2CORE_ROLE");

  /// @notice liquidity slippage tolerance
  uint256 public liquiditySlippageTolerance = 5e5; // 0.5%

  /// @notice The slippage tolernce in swaps in 1e8 precision
  uint256 public slippageTolerance = 5e5; // 0.5%

  // ================================ CONSTRUCTOR ================================ //
  constructor() {
    _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
    _setupRole(RDPXV2CORE_ROLE, msg.sender);
  }

  // ================================ ADMIN FUNCTIONS ================================ //
  /**
   * @notice Set the re-LP factor
   * @dev    Can only be called by admin
   * @param  _reLPFactor the bond discount factor
   **/
  function setreLpFactor(
    uint256 _reLPFactor
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(
      _reLPFactor > 0,
      "reLPContract: reLP factor must be greater than 0"
    );
    reLPFactor = _reLPFactor;

    emit LogSetReLpFactor(_reLPFactor);
  }

  /**
   * @notice Set the addresses of the contracts
   * @dev    Can only be called by admin
   * @param  _tokenA the token A address
   * @param  _tokenB the token B address
   * @param _pair the pair address
   * @param _rdpxV2Core the rdpxV2Core address
   * @param _tokenAReserve the token A reserve address
   * @param _amo the AMO address
   * @param _rdpxOracle the rdpx price oracle
   * @param _ammFactory the AMM Factory
   * @param _ammRouter the AMM Router
   **/
  function setAddresses(
    address _tokenA,
    address _tokenB,
    address _pair,
    address _rdpxV2Core,
    address _tokenAReserve,
    address _amo,
    address _rdpxOracle,
    address _ammFactory,
    address _ammRouter
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(
      _tokenA != address(0) &&
        _tokenB != address(0) &&
        _pair != address(0) &&
        _rdpxV2Core != address(0) &&
        _tokenAReserve != address(0) &&
        _amo != address(0) &&
        _rdpxOracle != address(0) &&
        _ammFactory != address(0) &&
        _ammRouter != address(0),
      "reLPContract: address cannot be 0"
    );
    addresses = Addresses({
      tokenA: _tokenA,
      tokenB: _tokenB,
      pair: _pair,
      rdpxV2Core: _rdpxV2Core,
      tokenAReserve: _tokenAReserve,
      amo: _amo,
      rdpxOracle: _rdpxOracle,
      ammFactory: _ammFactory,
      ammRouter: _ammRouter
    });

    IERC20WithBurn(addresses.pair).safeApprove(
      addresses.ammRouter,
      type(uint256).max
    );

    IERC20WithBurn(addresses.tokenA).safeApprove(
      addresses.ammRouter,
      type(uint256).max
    );

    IERC20WithBurn(addresses.tokenB).safeApprove(
      addresses.ammRouter,
      type(uint256).max
    );
  }

  /**
   * @notice sets the liquidity slippage tolerance
   * @dev    Can only be called by admin
   * @param  _liquiditySlippageTolerance the liquidity slippage tolerance
   */
  function setLiquiditySlippageTolerance(
    uint256 _liquiditySlippageTolerance
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(
      _liquiditySlippageTolerance > 0,
      "reLPContract: liquidity slippage tolerance must be greater than 0"
    );
    liquiditySlippageTolerance = _liquiditySlippageTolerance;
  }

  /**
   * @notice sets the slippage tolerance
   * @dev    Can only be called by admin
   * @param  _slippageTolerance the slippage tolerance
   */
  function setSlippageTolerance(
    uint256 _slippageTolerance
  ) external onlyRole(DEFAULT_ADMIN_ROLE) {
    require(
      _slippageTolerance > 0,
      "reLPContract: slippage tolerance must be greater than 0"
    );
    slippageTolerance = _slippageTolerance;
  }

  // ================================ RdpxV2Core FUNCTIONS ================================ //

  /**
   * @dev   re-LPs the pool
   * @param _amount the amount to reLP
   **/
  function reLP(uint256 _amount) external onlyRole(RDPXV2CORE_ROLE) {
    // get the pool reserves
    (address tokenASorted, address tokenBSorted) = UniswapV2Library.sortTokens(
      addresses.tokenA,
      addresses.tokenB
    );
    (uint256 reserveA, uint256 reserveB) = UniswapV2Library.getReserves(
      addresses.ammFactory,
      tokenASorted,
      tokenBSorted
    );

    TokenAInfo memory tokenAInfo = TokenAInfo(0, 0, 0);

    // get tokenA reserves
    tokenAInfo.tokenAReserve = IRdpxReserve(addresses.tokenAReserve)
      .rdpxReserve(); // rdpx reserves

    // get rdpx price
    tokenAInfo.tokenAPrice = IRdpxEthOracle(addresses.rdpxOracle)
      .getRdpxPriceInEth();

    tokenAInfo.tokenALpReserve = addresses.tokenA == tokenASorted
      ? reserveA
      : reserveB;

    uint256 baseReLpRatio = (reLPFactor *
      Math.sqrt(tokenAInfo.tokenAReserve) *
      1e2) / (Math.sqrt(1e18)); // 1e6 precision

    uint256 tokenAToRemove = ((((_amount * 4) * 1e18) /
      tokenAInfo.tokenAReserve) *
      tokenAInfo.tokenALpReserve *
      baseReLpRatio) / (1e18 * DEFAULT_PRECISION * 1e2);

    uint256 totalLpSupply = IUniswapV2Pair(addresses.pair).totalSupply();

    uint256 lpToRemove = (tokenAToRemove * totalLpSupply) /
      tokenAInfo.tokenALpReserve;

    // transfer LP tokens from the AMO
    IERC20WithBurn(addresses.pair).transferFrom(
      addresses.amo,
      address(this),
      lpToRemove
    );

    // calculate min amounts to remove
    uint256 mintokenAAmount = tokenAToRemove -
      ((tokenAToRemove * liquiditySlippageTolerance) / 1e8);
    uint256 mintokenBAmount = ((tokenAToRemove * tokenAInfo.tokenAPrice) /
      1e8) -
      ((tokenAToRemove * tokenAInfo.tokenAPrice) * liquiditySlippageTolerance) /
      1e16;

    (, uint256 amountB) = IUniswapV2Router(addresses.ammRouter).removeLiquidity(
      addresses.tokenA,
      addresses.tokenB,
      lpToRemove,
      mintokenAAmount,
      mintokenBAmount,
      address(this),
      block.timestamp + 10
    );

    address[] memory path;
    path = new address[](2);
    path[0] = addresses.tokenB;
    path[1] = addresses.tokenA;

    // calculate min amount of tokenA to be received
    mintokenAAmount =
      (((amountB / 2) * tokenAInfo.tokenAPrice) / 1e8) -
      (((amountB / 2) * tokenAInfo.tokenAPrice * slippageTolerance) / 1e16);

    uint256 tokenAAmountOut = IUniswapV2Router(addresses.ammRouter)
      .swapExactTokensForTokens(
        amountB / 2,
        mintokenAAmount,
        path,
        address(this),
        block.timestamp + 10
      )[path.length - 1];

    (, , uint256 lp) = IUniswapV2Router(addresses.ammRouter).addLiquidity(
      addresses.tokenA,
      addresses.tokenB,
      tokenAAmountOut,
      amountB / 2,
      0,
      0,
      address(this),
      block.timestamp + 10
    );

    // transfer the lp to the amo
    IERC20WithBurn(addresses.pair).safeTransfer(addresses.amo, lp);
    IUniV2LiquidityAmo(addresses.amo).sync();

    // transfer rdpx to rdpxV2Core
    IERC20WithBurn(addresses.tokenA).safeTransfer(
      addresses.rdpxV2Core,
      IERC20WithBurn(addresses.tokenA).balanceOf(address(this))
    );
    IRdpxV2Core(addresses.rdpxV2Core).sync();
  }

  // ================================ Events FUNCTIONS ================================ //

  event LogSetReLpFactor(uint256 _reLPFactor);
}
"},"contracts/reserve/IRdpxReserve.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
